'use strict';
(() => {
  const bridge=window.yawmiDesktop;if(!bridge)return;
  const $=id=>document.getElementById(id),escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const moods={happy:'مبسوط ☀️',calm:'هادي 🌿',busy:'مشغول شوية ☕',tired:'مرهق 🌙',sad:'زعلان شوية 🌧️',need_hug:'محتاج حضن 🤍'};
  const loves={love_you:'بحبك ❤️',missing_you:'وحشتني 🫶',thinking_of_you:'بفكّر فيك 💭',want_time:'نفسي في وقت سوا ✨',grateful:'ممتن لوجودك 🌷'};
  const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
  const options=map=>Object.entries(map).map(([v,label])=>`<option value="${v}">${label}</option>`).join('');
  const nav=document.createElement('nav');nav.className='couple-nav';nav.setAttribute('aria-label','مساحات يومي');
  nav.innerHTML='<button id="nav-together" class="selected">♡ مساحتنا</button><button id="nav-my-day">◷ جدولي</button>';
  document.querySelector('.header-left').prepend(nav);
  const page=document.createElement('section');page.id='couple-page';
  page.innerHTML=`<div class="couple-hero"><div><span class="eyebrow">يومي · بينا</span><h1>وقتنا يقرّبنا.</h1><p>يومك ويومها، وحاجات صغيرة تقول إنكم على بال بعض.</p></div><button class="primary miss-button" id="couple-miss">وحشتني ♡</button></div><p id="couple-feedback" role="status" class="couple-feedback"></p><div class="couple-grid"><div class="couple-column"><article class="couple-card partner-card"><span class="eyebrow">هي دلوقتي</span><h2 id="partner-heading">حالتها، بطريقتها</h2><div class="mood-pills"><span id="partner-mood">لسه مفيش حالة</span><span id="partner-love">مساحة لكلمة حلوة</span></div><p id="partner-note"></p><p id="couple-link-note" class="field-note">اربطوا التطبيقين من «مشاركة الجدول» عشان تظهر حالتكم وجداولكم.</p></article><article class="couple-card"><div class="couple-card-heading"><h2>جدولها</h2><input type="date" id="couple-date" aria-label="يوم جدول صديقتك"></div><div id="partner-plan" class="partner-plan"></div></article><article class="couple-card"><span class="eyebrow">تخططوا لحاجة سوا</span><h2>اقترح على يومها</h2><form id="couple-proposal-form"><label>النشاط<input id="proposal-name" maxlength="100" placeholder="نتمشّى أو نشرب حاجة سوا" required></label><div class="form-row"><label>اليوم<input id="proposal-date" type="date" required></label><label>الدقائق<input id="proposal-minutes" type="number" min="1" max="720" value="30" required></label></div><label>النوع<select id="proposal-kind"><option value="personal">وقت شخصي / سوا</option><option value="focus">تركيز</option><option value="movement">حركة</option><option value="break">بريك</option></select></label><p class="field-note">الاقتراح هيوصل لها، وهي تختار تضيفه لجدولها أو ترفضه.</p><button class="secondary" type="submit">ابعت الاقتراح ↗</button></form></article></div><div class="couple-column"><article class="couple-card"><span class="eyebrow">شاركها اللي جواك</span><h2>أنا حاسس بـ…</h2><form id="couple-profile-form"><div class="form-row"><label>مزاجي<select id="couple-mood">${options(moods)}</select></label><label>على بالي<select id="couple-love">${options(loves)}</select></label></div><label>كلمة ليها<input id="couple-note" maxlength="80" placeholder="حتى اليوم الزحمة، إنتِ فيه"></label><button class="secondary" type="submit">شارك حالتي</button></form></article><article class="couple-card warm-card"><span class="eyebrow">فكّرها بحاجة أو اطلبها لحظة</span><h2>منبّه ليها ♬</h2><form id="couple-alarm-form"><label>الرسالة<input id="couple-alarm-body" maxlength="140" placeholder="محتاجك لحظة، لما تقدري" required></label><label>الموعد — سيب اليوم فاضي لو دلوقتي<input id="couple-alarm-date" type="date"></label><div class="form-row"><label>الساعة<input id="couple-alarm-hour" type="number" min="1" max="12" value="9" required></label><label>الدقيقة<input id="couple-alarm-minute" type="number" min="0" max="59" value="0" required></label><label>الفترة<select id="couple-alarm-period"><option value="am">صباحًا</option><option value="pm">مساءً</option></select></label></div><p id="couple-alarm-preview" class="field-note">منبّه دلوقتي. هيفضل يرن لحد ما توقفه من موبايلها.</p><button class="secondary" type="submit">ابعت المنبّه</button></form><div id="couple-alarms" class="couple-inbox"></div></article><article class="couple-card"><h2>اقتراحات بينكم</h2><div id="couple-proposals" class="couple-inbox"></div></article></div></div>`;
  document.querySelector('main').prepend(page);document.body.classList.add('couple-mode');
  page.querySelector('.couple-hero h1').textContent='قريبين، وسط زحمة اليوم.';
  page.querySelector('.couple-hero p').textContent='مساحتكم الصغيرة… نشارك يومنا، ونسيب لبعض كلمة من القلب.';
  const heroMark=document.createElement('div');heroMark.className='couple-orbit';heroMark.setAttribute('aria-hidden','true');heroMark.innerHTML='<span>♡</span><i></i><b>بينا</b>';page.querySelector('.couple-hero').append(heroMark);
  function foldForm(formId,label){const form=$(formId),details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=label;form.before(details);details.append(summary,form);return details;}
  foldForm('couple-profile-form','غيّر حالتي');foldForm('couple-proposal-form','اكتب اقتراح جديد');foldForm('couple-alarm-form','منبّه جديد ليها');
  const ownSummary=document.createElement('p');ownSummary.id='couple-own-summary';ownSummary.className='own-state-summary';$('couple-profile-form').parentElement.before(ownSummary);
  const chat=document.createElement('article');chat.className='couple-card chat-card';chat.id='chat-card';
  chat.innerHTML='<div class="couple-card-heading"><h2>شاتنا ♡</h2><span class="eyebrow">رسالة صغيرة تقرّبكم</span></div><div id="chat-messages" class="chat-messages" role="log" aria-live="polite"></div><form id="chat-form"><label>رسالتك<textarea id="chat-body" maxlength="1000" rows="2" placeholder="قول لها اللي على بالك…" required></textarea></label><button id="chat-send" class="primary" type="submit">ابعت ♡</button><small id="chat-status" role="status"></small></form><p class="field-note">آخر ٨٠ رسالة · إشعارات هادية · محتاجين اتصال ويومي مفتوح على الكمبيوتر.</p>';
  page.querySelector('.couple-column').prepend(chat);
  const chatNav=document.createElement('button');chatNav.textContent='شاتنا';nav.append(chatNav);
  const openChat=()=>{mode(true);chat.scrollIntoView({behavior:'smooth',block:'start'});$('chat-body').focus();};chatNav.onclick=openChat;
  $('chat-form').onsubmit=async event=>{event.preventDefault();const text=$('chat-body').value.trim();if(!text)return;$('chat-send').disabled=true;$('chat-status').textContent='جاري الإرسال…';if(await action('chat',{body:text})){if($('chat-body').value.trim()===text)$('chat-body').value='';$('chat-status').textContent='اتحفظت في الشات ✓';}else $('chat-status').textContent='متعذّر الإرسال؛ رسالتك لسه موجودة.';$('chat-send').disabled=false;};
  let chatFingerprint='';
  $('couple-date').value=$('proposal-date').value=today();
  let current,initializedProfile=false;
  const message=text=>{$('couple-feedback').textContent=text;};
  function mode(couple){document.body.classList.toggle('couple-mode',couple);$('nav-together').classList.toggle('selected',couple);$('nav-my-day').classList.toggle('selected',!couple);}
  $('nav-together').onclick=()=>mode(true);$('nav-my-day').onclick=()=>mode(false);
  async function action(name,input){
    try{const result=await bridge.couple(name,input);if(!result.ok)throw Error(result.error);if(result.couple)renderCouple(result.couple);return true;}
    catch(error){message(error.message||'تعذّر الاتصال. جرّب تاني.');return false;}
  }
  function renderCouple(couple){
    current=couple;const profile=couple.partnerProfile||{};
    const messages=couple.messages||[],fingerprint=JSON.stringify(messages);if(fingerprint!==chatFingerprint){const box=$('chat-messages'),nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<70;chatFingerprint=fingerprint;box.innerHTML=messages.map(m=>`<div class="chat-bubble ${m.sender==='desktop'?'own':'partner'}"><b>${m.sender==='desktop'?'أنا':'هي'}</b><p>${escape(m.body)}</p><small>${m.createdAt?escape(new Date(m.createdAt).toLocaleString('ar-EG',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',hour12:true})):'جاري الحفظ…'}</small></div>`).join('')||'<p class="field-note">ابدأوا بأول رسالة ♡</p>';if(nearBottom)box.scrollTop=box.scrollHeight;}

    $('partner-heading').textContent=profile.name?`يوم ${profile.name}`:'حالتها، بطريقتها';
    $('partner-mood').textContent=moods[profile.mood]||'لسه مفيش حالة';$('partner-love').textContent=loves[profile.love]||'مساحة لكلمة حلوة';$('partner-note').textContent=profile.note||'';
    $('couple-own-summary').textContent=(moods[couple.ownProfile?.mood]||'شاركها مزاجك')+'  ·  '+(loves[couple.ownProfile?.love]||'وكلمة من قلبك');
    if(!initializedProfile&&couple.ownProfile?.mood){$('couple-mood').value=couple.ownProfile.mood;$('couple-love').value=couple.ownProfile.love;$('couple-note').value=couple.ownProfile.note||'';initializedProfile=true;}
    const day=couple.partnerDay||{start:'09:00',items:[]};
    $('partner-plan').innerHTML=window.yawmiTime.timeline(day,couple.date||today()).map(({item,start,end})=>`<div class="partner-activity ${item.done?'is-done':''}"><span class="partner-kind">${item.kind==='break'?'☕':item.done?'✓':'◷'}</span><div><strong>${escape(item.name)}</strong><small>${item.minutes===0?escape(window.yawmiTime.activityRecord(item)):`${start===null?"بعد النشاط المفتوح":escape(window.yawmiTime.clock(start))} — ${end===null?"بدون نهاية محددة":escape(window.yawmiTime.clock(end))}${item.actualStart?" · بداية فعلية":""}`}</small>${item.deadline&&!item.done?`<small class="live-countdown" data-deadline="${Number(item.deadline)}"></small>`:''}</div></div>`).join('')||'<p class="field-note">لسه مفيش أنشطة متشاركة لليوم ده.</p>';
    $('couple-proposals').innerHTML=(couple.proposals||[]).map(p=>`<div class="couple-inbox-row"><strong>${escape(p.name)}</strong><p>${escape(p.date)} · ${Number(p.minutes).toLocaleString('ar-EG')} دقيقة</p>${p.target==='desktop'?`<div class="inline-actions"><button class="secondary" data-accept="${escape(p.id)}">أوافق وأضيفه</button><button class="text-button" data-reject="${escape(p.id)}">مش مناسب</button></div>`:'<small>اقتراحك عندها · مستني ردها</small>'}</div>`).join('')||'<p class="field-note">مفيش اقتراحات مستنية رد دلوقتي.</p>';
    $('couple-alarms').innerHTML=(couple.alarms||[]).map(a=>`<div class="couple-inbox-row"><strong>${escape(a.body)}</strong><p>${a.target==='desktop'?'ليّ':'ليها'} · ${escape(new Date(a.dueAt).toLocaleString('ar-EG',{weekday:'short',hour:'numeric',minute:'2-digit',hour12:true}))}</p><button class="text-button" data-cancel-alarm="${escape(a.id)}">إلغاء المنبّه</button></div>`).join('');
  }
  page.addEventListener('click',async event=>{
    const accept=event.target.closest('[data-accept]'),reject=event.target.closest('[data-reject]'),cancel=event.target.closest('[data-cancel-alarm]');
    if(accept||reject){const node=accept||reject;if(await action('respond',{id:node.dataset.accept||node.dataset.reject,decision:accept?'accepted':'rejected'}))message(accept?'الاقتراح اتضاف لجدولك ✓':'الرد اتسجّل');}
    else if(cancel&&await action('cancelAlarm',cancel.dataset.cancelAlarm))message('المنبّه اتلغى');
  });
  $('couple-date').onchange=()=>action('watch',$('couple-date').value);
  $('couple-profile-form').onsubmit=async e=>{e.preventDefault();if(await action('profile',{mood:$('couple-mood').value,love:$('couple-love').value,note:$('couple-note').value}))message('حالتك اتشاركت معاها ♡');};
  $('couple-miss').onclick=async()=>{const button=$('couple-miss');button.disabled=true;if(await action('missYou'))message('بعتّلها إشعار «وحشتني» ♡');setTimeout(()=>button.disabled=false,10000);};
  $('couple-proposal-form').onsubmit=async e=>{e.preventDefault();if(await action('propose',{date:$('proposal-date').value,name:$('proposal-name').value,minutes:Number($('proposal-minutes').value),kind:$('proposal-kind').value})){message('اقتراحك اتبعت. هي اللي هتختار تضيفه.');$('proposal-name').value='';}};
  function alarmDue(){if(!$('couple-alarm-date').value)return Date.now();const hour=Number($('couple-alarm-hour').value)%12+($('couple-alarm-period').value==='pm'?12:0);return new Date($('couple-alarm-date').value+'T'+String(hour).padStart(2,'0')+':'+String(Number($('couple-alarm-minute').value)).padStart(2,'0')).getTime();}
  for(const id of ['couple-alarm-date','couple-alarm-hour','couple-alarm-minute','couple-alarm-period'])$(id).oninput=()=>{$('couple-alarm-preview').textContent=$('couple-alarm-date').value?'هيوصل منبّه لمعاد '+new Date(alarmDue()).toLocaleString('ar-EG',{dateStyle:'short',timeStyle:'short',hour12:true}):'منبّه دلوقتي. هيفضل يرن لحد ما توقفه من موبايلها.';};
  $('couple-alarm-form').onsubmit=async e=>{e.preventDefault();if(await action('alarm',{body:$('couple-alarm-body').value,dueAt:alarmDue()}))message('المنبّه اتسجّل. الوصول حسب الإنترنت وإعدادات الموبايل.');};
  bridge.onSharingStatus(status=>{$('couple-link-note').textContent=status.viewers?.length?status.message:'اربطوا التطبيقين من «مشاركة الجدول» عشان تظهر حالتكم وجداولكم.';if(status.couple)renderCouple(status.couple);});
  bridge.onPlanUpdated(state=>window.dispatchEvent(new CustomEvent('yawmi:accepted-proposal',{detail:state})));
  bridge.onCoupleEvent(event=>{if(event.type==='open-chat'){openChat();return;}message(event.type==='chat'?'رسالة جديدة في شاتنا ♡':event.body);window.dispatchEvent(new CustomEvent('yawmi:message',{detail:event.body}));});
  bridge.sharing('status').then(result=>{if(result.status?.couple)renderCouple(result.status.couple);}).catch(()=>{});
  setInterval(()=>{for(const label of page.querySelectorAll('[data-deadline]')){const seconds=Math.max(0,Math.ceil((Number(label.dataset.deadline)-Date.now())/1000));label.textContent=seconds?`شغال · ${Math.floor(seconds/60).toLocaleString('ar-EG')}:${String(seconds%60).padStart(2,'0')}`:'وصل لنهاية وقته';}},1000);
})();
